        b'c' => b'g',
        b'g' => b'c',
        b't' | b'u' => b'a',
        b'r' => b'y',
        b'y' => b'r',
        b'k' => b'm',
        b'm' => b'k',
        b's' => b's',
        b'w' => b'w',
        b'b' => b'v',
        b'd' => b'h',
        b'h' => b'd',
        b'v' => b'b',
        b'x' => b'x',
        _ => b'n',
    };
    if base.is_ascii_lowercase() {
        comp
    } else {
        comp.to_ascii_uppercase()
    }
}

pub fn reverse_complement(seq: &[u8]) -> Vec<u8> {
    seq.iter().rev().map(|&b| complement_base(b)).collect()
}

pub fn upper_seq(seq: &mut [u8]) {
    for base in seq {
        *base = base.to_ascii_uppercase();
    }
}

pub fn lower_base(base: u8) -> u8 {
    base.to_ascii_lowercase()
}

pub fn mask_char(base: u8, ch: u8) -> u8 {
    match ch {
        b'X' => base.to_ascii_uppercase(),
        b'x' => base.to_ascii_lowercase(),
        other => other,
    }
}

pub fn is_n(base: u8) -> bool {
    matches!(base.to_ascii_lowercase(), b'n' | b'x')
}

pub fn is_het2(base: u8) -> bool {
    matches!(base.to_ascii_lowercase(), b'r' | b'y' | b'k' | b'm' | b's' | b'w')
}

pub fn het_class(base: u8) -> Option<&'static [u8]> {
    match base.to_ascii_lowercase() {
        b'a' => Some(b"A"),
        b'c' => Some(b"C"),
        b'g' => Some(b"G"),
        b't' | b'u' => Some(b"T"),
        b'r' => Some(b"AG"),
        b'y' => Some(b"CT"),
        b'k' => Some(b"GT"),
        b'm' => Some(b"AC"),
        b's' => Some(b"CG"),
        b'w' => Some(b"AT"),
        b'b' => Some(b"CGT"),
        b'd' => Some(b"AGT"),
        b'h' => Some(b"ACT"),
        b'v' => Some(b"ACG"),
        b'n' | b'x' => Some(b"ACGT"),
        _ => None,
    }
}

pub fn encode_alleles(bits: u8, lower: bool, empty_char: u8) -> u8 {
    let base = match bits {
        0b0001 => b'A',
        0b0010 => b'C',
        0b0100 => b'G',
        0b1000 => b'T',
        0b0101 => b'R',
        0b1010 => b'Y',
        0b1100 => b'K',
        0b0011 => b'M',
        0b0110 => b'S',
        0b1001 => b'W',
        0b1110 => b'B',
        0b1101 => b'D',
        0b1011 => b'H',
        0b0111 => b'V',
        0b1111 => b'N',
        _ => empty_char,
    };
    if lower {
        base.to_ascii_lowercase()
    } else {
        base
    }
}

pub fn allele_bits(base: u8) -> u8 {
    match base.to_ascii_lowercase() {
        b'a' => 0b0001,
        b'c' => 0b0010,
        b'g' => 0b0100,
        b't' | b'u' => 0b1000,
        b'r' => 0b0101,
        b'y' => 0b1010,
        b'k' => 0b1100,
        b'm' => 0b0011,
        b's' => 0b0110,
        b'w' => 0b1001,
        b'b' => 0b1110,
        b'd' => 0b1101,
        b'h' => 0b1011,
        b'v' => 0b0111,
        b'n' | b'x' => 0b1111,
        _ => 0,
    }
}

pub fn record_format(record: &Record) -> Format {
    if record.qual.is_some() {
        Format::Fastq
    } else {
        Format::Fasta
    }
}

