+fn take_short_value(
+    cmd: &str,
+    opt: char,
+    chars: &[char],
+    pos: &mut usize,
+    args: &[String],
+    idx: &mut usize,
+) -> Option<String> {
+    if *pos + 1 < chars.len() {
+        let value: String = chars[*pos + 1..].iter().collect();
+        *pos = chars.len();
