+
+fn n_tracts(seq: &[u8], min_len: usize) -> Vec<(usize, usize)> {
+    let mut out = Vec::new();
+    let mut i = 0usize;
+    while i < seq.len() {
+        if is_n(seq[i]) {
+            let start = i;
+            while i < seq.len() && is_n(seq[i]) {
+                i += 1;
+            }
+            if i - start >= min_len {
